#pragma once
/**
 * @file NetworkClosedLoopRunEnd.hpp
 * @brief Run-end report of the closed-loop integer-recovery harness (the held-out consumer).
 *
 * The run-end reports defined in NetworkClosedLoopRunEnd.cpp; each is a row of kNetworkRunEndReports
 * (network/runend/NetworkRunEnd.hpp).
 */

namespace GnssProcessor {

// ---- Run-end reports (card NOM step TD1b; generated by scripts/nom_td_cut.py) ----

struct NetworkRunEndView;

/**
 * @brief Run-end report: the closed-loop integer-recovery harness.
 *
 * The closed-loop integer-recovery harness of the held-out consumer: the mode, the fix
 * rate, the position error and the verdict, the producer's per-card lines (CST, JT, PBH,
 * LAH, SMH, SCL, SMD, MS) and the consumer's (CC, PBT, ALC, PBH), and the consumer's
 * three summaries, which go to the rt_engine logger.
 *
 * Gate: returns 0 at once unless `closed_loop_on && consumer`.
 *
 * @param v The run at its end (network/runend/NetworkRunEnd.hpp).
 * @return 0 (this report does not set the exit code).
 */
int networkClosedLoopRunEnd(const NetworkRunEndView& v);

// ---- End of the run-end reports ----

} // namespace GnssProcessor
